package com.northstar.crm.security;
import com.northstar.crm.domain.*;import org.junit.jupiter.api.*;import org.springframework.security.access.AccessDeniedException;import java.time.LocalDate;import static com.northstar.crm.domain.DomainTypes.*;import static org.junit.jupiter.api.Assertions.*;
class AccessPolicyTest {private final AccessPolicy policy=new AccessPolicy();private final String hash="$2a$12$abcdefghijklmnopqrstuv12345678901234567890123456789012";@Test void customerIsRestrictedToOwnOrganization(){var owner=new UserAccount("manager@test.local","Manager",hash,Role.ACCOUNT_MANAGER,null);var own=new Organization("Own","Scale",OrganizationStatus.ACTIVE,Health.GOOD,80,owner.getId(),LocalDate.now(),"bill@test.local","");var other=new Organization("Other","Scale",OrganizationStatus.ACTIVE,Health.GOOD,80,owner.getId(),LocalDate.now(),"bill@test.local","");var customer=new UserAccount("customer@test.local","Customer",hash,Role.CUSTOMER_CONTACT,own.getId());assertDoesNotThrow(()->policy.requireOrganization(customer,own));assertThrows(AccessDeniedException.class,()->policy.requireOrganization(customer,other));}@Test void customerCannotReadInternalDocument(){var owner=new UserAccount("manager@test.local","Manager",hash,Role.ACCOUNT_MANAGER,null);var org=new Organization("Own","Scale",OrganizationStatus.ACTIVE,Health.GOOD,80,owner.getId(),LocalDate.now(),"bill@test.local","");var customer=new UserAccount("customer@test.local","Customer",hash,Role.CUSTOMER_CONTACT,org.getId());var shared=new CustomerDocument(org.getId(),owner.getId(),"shared.txt","safe.txt","text/plain",3,DocumentCategory.CONTRACT,Visibility.CUSTOMER_VISIBLE,"");var internal=new CustomerDocument(org.getId(),owner.getId(),"internal.txt","safe2.txt","text/plain",3,DocumentCategory.CONTRACT,Visibility.INTERNAL,"");assertDoesNotThrow(()->policy.requireDocument(customer,shared));assertThrows(AccessDeniedException.class,()->policy.requireDocument(customer,internal));}}
